content.arguments:
{"command": "$t = Join-Path $env:TEMP 'yanxia-review'
$script = Join-Path $t 'win.ps1'
$code = @'
param(
  [Parameter(Mandatory=$true)][string]$Action,
  [int]$X = 0, [int]$Y = 0,
  [string]$Name = '',
  [string]$Text = '',
  [int]$X2 = 0, [int]$Y2 = 0,
  [int]$Steps = 25,
  [switch]$All
)
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
if (-not ([System.Management.Automation.PSTypeName]'WinApi').Type) {
Add-Type @"
using System;
using System.Runtime.InteropServices;
public class WinApi {
  [DllImport("user32.dll")] public static extern bool SetCursorPos(int x, int y);
  [DllImport("user32.dll")] public static extern void mouse_event(uint f, uint dx, uint dy, uint d, IntPtr e);
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr h);
  [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr h, int c);
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out RECT r);
  [DllImport("user32.dll")] public static extern bool GetClientRect(IntPtr h, out RECT r);
  [DllImport("user32.dll")] public static extern bool ClientToScreen(IntPtr h, ref POINT p);
  [DllImport("user32.dll")] public static extern uint GetDpiForWindow(IntPtr h);
  [DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow();
  [StructLayout(LayoutKind.Sequential)] public struct RECT { public int Left, Top, Right, Bottom; }
  [StructLayout(LayoutKind.Sequential)] public struct POINT { public int X, Y; }
}
"@
}
function Get-GameProc {
  $p = Get-Process | Where-Object { $_.MainWindowHandle -ne 0 -and ($_.ProcessName -like '*檐下*' -or $_.ProcessName -like '*Godot*') } | Select-Object -First 1
  return $p
}
function Get-WinRect($proc) {
  $r = New-Object WinApi+RECT
  [void][WinApi]::GetWindowRect($proc.MainWindowHandle, [ref]$r)
  return $r
}
function Shot([string]$path, [switch]$FullScreen) {
  $b = [System.Windows.Forms.Screen]::PrimaryScreen.Bounds
  $proc = Get-GameProc
  if ($FullScreen -or -not $proc) {
    $x = $b.X; $y = $b.Y; $w = $b.Width; $h = $b.Height
  } else {
    $r = Get-WinRect $proc
    $x = $r.Left; $y = $r.Top; $w = $r.Right - $r.Left; $h = $r.Bottom - $r.Top
  }
  $bmp = New-Object System.Drawing.Bitmap $w, $h
  $g = [System.Drawing.Graphics]::FromImage($bmp)
  $g.CopyFromScreen($x, $y, 0, 0, $bmp.Size)
  $bmp.Save($path, [System.Drawing.Imaging.ImageFormat]::Png)
  $g.Dispose(); $bmp.Dispose()
  return "$path|${w}x${h}|origin=${x},${y}"
}
function MoveTo([int]$x, [int]$y, [int]$steps) {
  $cur = [System.Windows.Forms.Cursor]::Position
  for ($i = 1; $i -le $steps; $i++) {
    $nx = [int]($cur.X + ($x - $cur.X) * $i / $steps)
    $ny = [int]($cur.Y + ($y - $cur.Y) * $i / $steps)
    [void][WinApi]::SetCursorPos($nx, $ny)
    Start-Sleep -Milliseconds 8
  }
}
switch ($Action) {
  'shot'      { Shot $Name -FullScreen:$FullScreen }
  'rect'      {
    $proc = Get-GameProc
    if (-not $proc) { 'no-window'; break }
    $r = Get-WinRect $proc
    "title=$($proc.MainWindowTitle) pid=$($proc.Id) rect=$($r.Left),$($r.Top),$($r.Right),$($r.Bottom) size=$($r.Right-$r.Left)x$($r.Bottom-$r.Top) dpi=$([WinApi]::GetDpiForWindow($proc.MainWindowHandle))"
  }
  'focus'     {
    $proc = Get-GameProc
    if (-not $proc) { 'no-window'; break }
    [void][WinApi]::ShowWindow($proc.MainWindowHandle, 9)
    [void][WinApi]::SetForegroundWindow($proc.MainWindowHandle)
    Start-Sleep -Milliseconds 300
    "focused $($proc.Id)"
  }
  'click'     {
    [void][WinApi]::SetCursorPos($X, $Y)
    Start-Sleep -Milliseconds 120
    [WinApi]::mouse_event(2, 0, 0, 0, [IntPtr]::Zero)
    Start-Sleep -Milliseconds 60
    [WinApi]::mouse_event(4, 0, 0, 0, [IntPtr]::Zero)
    "clicked $X,$Y"
  }
  'clickrel'  {
    # X,Y given relative to client area of the game window
    $proc = Get-GameProc
    $pt = New-Object WinApi+POINT
    $pt.X = $X; $pt.Y = $Y
    [void][WinApi]::ClientToScreen($proc.MainWindowHandle, [ref]$pt)
    [void][WinApi]::SetCursorPos($pt.X, $pt.Y)
    Start-Sleep -Milliseconds 120
    [WinApi]::mouse_event(2, 0, 0, 0, [IntPtr]::Zero)
    Start-Sleep -Milliseconds 60
    [WinApi]::mouse_event(4, 0, 0, 0, [IntPtr]::Zero)
    "clicked client $X,$Y -> screen $($pt.X),$($pt.Y)"
  }
  'drag'      {
    [void][WinApi]::SetCursorPos($X, $Y)
    Start-Sleep -Milliseconds 150
    [WinApi]::mouse_event(2, 0, 0, 0, [IntPtr]::Zero)
    Start-Sleep -Milliseconds 120
    MoveTo $X2 $Y2 $Steps
    Start-Sleep -Milliseconds 150
    [WinApi]::mouse_event(4, 0, 0, 0, [IntPtr]::Zero)
    "dragged $X,$Y -> $X2,$Y2"
  }
  'move'      { MoveTo $X $Y $Steps; "moved $X,$Y" }
  'key'       {
    $proc = Get-GameProc
    [void][WinApi]::SetForegroundWindow($proc.MainWindowHandle)
    Start-Sleep -Milliseconds 200
    [System.Windows.Forms.SendKeys]::SendWait($Text)
    "sent keys: $Text"
  }
  default     { "unknown action $Action" }
}
'@
Set-Content -Path $script -Value $code -Encoding UTF8
"script written: $script"
Get-CimInstance Win32_VideoController | Select-Object Name,CurrentHorizontalResolution,CurrentVerticalResolution | Format-Table -AutoSize", "description": "Write window automation helper script"}

