content.arguments:
{"command": "$t = Join-Path $env:TEMP 'yanxia-review'
$script = Join-Path $t 'game.ps1'
$code = @'
param(
  [Parameter(Mandatory=$true)][string]$Action,
  [int]$X = 0, [int]$Y = 0,
  [int]$X2 = 0, [int]$Y2 = 0,
  [string]$Name = '',
  [string]$Text = '',
  [int]$Steps = 20,
  [int]$Wait = 400,
  [int]$Hold = 0,
  [switch]$All
)
$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
if (-not ([System.Management.Automation.PSTypeName]'WinApi2').Type) {
Add-Type @"
using System;
using System.Runtime.InteropServices;
public class WinApi2 {
  [DllImport("user32.dll")] public static extern bool SetCursorPos(int x, int y);
  [DllImport("user32.dll")] public static extern void mouse_event(uint f, uint dx, uint dy, uint d, IntPtr e);
  [DllImport("user32.dll")] public static extern bool SetForegroundWindow(IntPtr h);
  [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr h, int c);
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out RECT r);
  [DllImport("user32.dll")] public static extern bool GetClientRect(IntPtr h, out RECT r);
  [DllImport("user32.dll")] public static extern bool ClientToScreen(IntPtr h, ref POINT p);
  [DllImport("user32.dll")] public static extern bool SetWindowPos(IntPtr h, IntPtr after, int x, int y, int cx, int cy, uint flags);
  [DllImport("user32.dll")] public static extern uint GetDpiForWindow(IntPtr h);
  [DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow();
  [StructLayout(LayoutKind.Sequential)] public struct RECT { public int Left, Top, Right, Bottom; }
  [StructLayout(LayoutKind.Sequential)] public struct POINT { public int X, Y; }
}
"@
}
function Get-GameProc {
  return (Get-Process | Where-Object { $_.MainWindowHandle -ne 0 -and ($_.ProcessName -match '[\u4e00-\u9fff]' -or $_.ProcessName -like '*Godot*') } | Select-Object -First 1)
}
function Get-ClientInfo($proc) {
  $cr = New-Object WinApi2+RECT
  [void][WinApi2]::GetClientRect($proc.MainWindowHandle, [ref]$cr)
  $pt = New-Object WinApi2+POINT
  $pt.X = 0; $pt.Y = 0
  [void][WinApi2]::ClientToScreen($proc.MainWindowHandle, [ref]$pt)
  return @{ W = $cr.Right - $cr.Left; H = $cr.Bottom - $cr.Top; X = $pt.X; Y = $pt.Y }
}
function To-Screen($ci, [int]$gx, [int]$gy) {
  $sx = [int]($ci.X + $gx * $ci.W / 540.0)
  $sy = [int]($ci.Y + $gy * $ci.H / 960.0)
  return @{ X = $sx; Y = $sy }
}
function Click-Screen([int]$sx, [int]$sy) {
  [void][WinApi2]::SetCursorPos($sx, $sy)
  Start-Sleep -Milliseconds 130
  [WinApi2]::mouse_event(2, 0, 0, 0, [IntPtr]::Zero)
  Start-Sleep -Milliseconds 70
  [WinApi2]::mouse_event(4, 0, 0, 0, [IntPtr]::Zero)
}
function Do-Shot([string]$path, [string]$mode) {
  $proc = Get-GameProc
  $b = [System.Windows.Forms.Screen]::PrimaryScreen.Bounds
  if ($mode -eq 'full' -or -not $proc) {
    $x = $b.X; $y = $b.Y; $w = $b.Width; $h = $b.Height; $scale = $false
  } elseif ($mode -eq 'client') {
    $ci = Get-ClientInfo $proc
    $x = $ci.X; $y = $ci.Y; $w = $ci.W; $h = $ci.H; $scale = $true
  } else {
    $r = New-Object WinApi2+RECT
    [void][WinApi2]::GetWindowRect($proc.MainWindowHandle, [ref]$r)
    $x = $r.Left; $y = $r.Top; $w = $r.Right - $r.Left; $h = $r.Bottom - $r.Top; $scale = $false
  }
  $bmp = New-Object System.Drawing.Bitmap $w, $h
  $g = [System.Drawing.Graphics]::FromImage($bmp)
  $g.CopyFromScreen($x, $y, 0, 0, $bmp.Size)
  $g.Dispose()
  if ($scale) {
    $big = New-Object System.Drawing.Bitmap 540, 960
    $g2 = [System.Drawing.Graphics]::FromImage($big)
    $g2.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
    $g2.DrawImage($bmp, 0, 0, 540, 960)
    $g2.Dispose()
    $big.Save($path, [System.Drawing.Imaging.ImageFormat]::Png)
    $big.Dispose()
  } else {
    $bmp.Save($path, [System.Drawing.Imaging.ImageFormat]::Png)
  }
  $bmp.Dispose()
  return "$path|${w}x${h}|origin=${x},${y}"
}
$proc = Get-GameProc
switch ($Action) {
  'rect' {
    if (-not $proc) { 'no-window'; break }
    $r = New-Object WinApi2+RECT
    [void][WinApi2]::GetWindowRect($proc.MainWindowHandle, [ref]$r)
    $ci = Get-ClientInfo $proc
    "title=$($proc.MainWindowTitle) pid=$($proc.Id) win=$($r.Left),$($r.Top),$($r.Right),$($r.Bottom) client=$($ci.W)x$($ci.H)@$($ci.X),$($ci.Y) dpi=$([WinApi2]::GetDpiForWindow($proc.MainWindowHandle))"
  }
  'topmost' {
    if (-not $proc) { 'no-window'; break }
    [void][WinApi2]::ShowWindow($proc.MainWindowHandle, 9)
    [void][WinApi2]::SetWindowPos($proc.MainWindowHandle, [IntPtr](-1), $X, $Y, 0, 0, 0x0041)
    Start-Sleep -Milliseconds 400
    "topmost at $X,$Y"
  }
  'focus' {
    if (-not $proc) { 'no-window'; break }
    [void][WinApi2]::ShowWindow($proc.MainWindowHandle, 9)
    [void][WinApi2]::SetForegroundWindow($proc.MainWindowHandle)
    Start-Sleep -Milliseconds 300
    "focused $($proc.Id)"
  }
  'shot'    { if ($All) { Do-Shot $Name 'full' } else { Do-Shot $Name 'window' } }
  'shotfull'   { Do-Shot $Name 'full' }
  'shotclient' { Do-Shot $Name 'client' }
  'click' {
    Click-Screen $X $Y
    Start-Sleep -Milliseconds $Wait
    "clicked screen $X,$Y"
  }
  'clickg' {
    $ci = Get-ClientInfo $proc
    $s = To-Screen $ci $X $Y
    Click-Screen $s.X $s.Y
    Start-Sleep -Milliseconds $Wait
    "clicked game($X,$Y) -> screen($($s.X),$($s.Y)) client=$($ci.W)x$($ci.H)@$($ci.X),$($ci.Y)"
  }
  'dragg' {
    $ci = Get-ClientInfo $proc
    $a = To-Screen $ci $X $Y
    $b2 = To-Screen $ci $X2 $Y2
    [void][WinApi2]::SetCursorPos($a.X, $a.Y)
    Start-Sleep -Milliseconds 150
    [WinApi2]::mouse_event(2, 0, 0, 0, [IntPtr]::Zero)
    Start-Sleep -Milliseconds 150
    for ($i = 1; $i -le $Steps; $i++) {
      $nx = [int]($a.X + ($b2.X - $a.X) * $i / $Steps)
      $ny = [int]($a.Y + ($b2.Y - $a.Y) * $i / $Steps)
      [void][WinApi2]::SetCursorPos($nx, $ny)
      Start-Sleep -Milliseconds 12
    }
    Start-Sleep -Milliseconds 150
    [WinApi2]::mouse_event(4, 0, 0, 0, [IntPtr]::Zero)
    Start-Sleep -Milliseconds $Wait
    "dragged game($X,$Y) -> ($X2,$Y2)"
  }
  'path' {
    # draw a polyline through game-space points passed as "x1,y1;x2,y2;..."
    $ci = Get-ClientInfo $proc
    $pts = $Text.Split(';') | Where-Object { $_ -ne '' }
    $first = $true
    foreach ($p in $pts) {
      $xy = $p.Split(',')
      $s = To-Screen $ci ([int]$xy[0]) ([int]$xy[1])
      if ($first) {
        [void][WinApi2]::SetCursorPos($s.X, $s.Y)
        Start-Sleep -Milliseconds 120
        [WinApi2]::mouse_event(2, 0, 0, 0, [IntPtr]::Zero)
        Start-Sleep -Milliseconds 120
        $first = $false
      } else {
        [void][WinApi2]::SetCursorPos($s.X, $s.Y)
        Start-Sleep -Milliseconds 12
      }
    }
    Start-Sleep -Milliseconds 120
    [WinApi2]::mouse_event(4, 0, 0, 0, [IntPtr]::Zero)
    Start-Sleep -Milliseconds $Wait
    "drew path with $($pts.Count) points"
  }
  'key' {
    [void][WinApi2]::SetForegroundWindow($proc.MainWindowHandle)
    Start-Sleep -Milliseconds 250
    [System.Windows.Forms.SendKeys]::SendWait($Text)
    Start-Sleep -Milliseconds $Wait
    "sent keys: $Text"
  }
  'holdkeys' {
    [void][WinApi2]::SetForegroundWindow($proc.MainWindowHandle)
    Start-Sleep -Milliseconds 250
    foreach ($k in $Text.Split(',')) {
      if ($k -eq '') { continue }
      [System.Windows.Forms.SendKeys]::SendWait($k)
      Start-Sleep -Milliseconds ([int]($Hold / [Math]::Max(1, $Text.Split(',').Count)))
    }
    "held keys: $Text for $Hold ms"
  }
  default { "unknown action $Action" }
}
'@
Set-Content -Path $script -Value $code -Encoding UTF8
& $script -Action rect
& $script -Action topmost -X 20 -Y 20
Start-Sleep -Seconds 1
& $script -Action shotclient -Name (Join-Path $t '04-client.png')", "description": "Write improved helper and capture client area"}

