# Read-only review harness for 《檐下千秋》 (independent of the project's own tests).
# This file lives in a throwaway copy of the client and is never part of the repository.
# Every interaction goes through the real Godot input pipeline (Viewport.push_input),
# so buttons are hit-tested and pressed exactly like a hardware mouse click.

const OFF_HAND := 0.04

var main: Node
var game: Node
var shots := ""
var shot_no := 0
var fails: Array[String] = []
var compared := false
var dialog_cancel_tested := false

const JOIN_ANSWERS := {
	"beam_left": "left", "beam_center": "center", "beam_right": "right",
	"stage_step": "梅", "stage_backdrop": "中", "archway_join": "中"
}
const CHOICE_ANSWERS := {
	"guest_word": "宁", "opera_role": "旦", "archway_grade": "四柱三间"
}
const SKILL_STEPS := {
	"drum_purify": "藻井", "craftsman_anchor": "斗拱", "craftsman_trigger": "飞檐",
	"tower_anchor": "斗拱", "tower_purify": "藻井"
}
const EVENTS := [
	["prologue", "prologue_bridge", "桥上平安"],
	["temple", "temple_incense", "香火断"],
	["temple", "temple_guest", "檐下客"],
	["temple", "temple_drum", "社鼓声"],
	["opera", "opera_opening", "开场锣"],
	["opera", "opera_master", "名角儿"],
	["archway", "archway_form", "四柱三间"],
	["archway", "archway_craftsman", "无名匠"],
	["tower", "tower_ascent", "登塔"],
	["tower", "tower_ledger", "千层墨"],
]

func _initialize() -> void:
	_run.call_deferred()

func log(msg: String) -> void:
	print("[REVIEW %7d] %s" % [Time.get_ticks_msec(), msg])

func fail(msg: String) -> void:
	fails.append(msg)
	print("[REVIEW-FAIL %7d] %s" % [Time.get_ticks_msec(), msg])

func shot(name: String) -> void:
	shot_no += 1
	await process_frame
	await process_frame
	RenderingServer.force_draw()
	var img: Image = root.get_texture().get_image()
	var path: String = shots.path_join("%03d-%s.png" % [shot_no, name])
	img.save_png(path)
	log("shot %s" % path)

func collect_buttons(node: Node, out: Array) -> void:
	for child in node.get_children():
		if child is Button:
			out.append(child)
		collect_buttons(child, out)

func find_button(text: String, exact: bool = false) -> Button:
	var list: Array = []
	collect_buttons(main, list)
	for b in list:
		if not b.is_visible_in_tree():
			continue
		var hit: bool = (b.text == text) if exact else b.text.contains(text)
		if hit:
			return b
	return null

func find_buttons_like(text: String) -> Array:
	var list: Array = []
	collect_buttons(main, list)
	var out: Array = []
	for b in list:
		if b.is_visible_in_tree() and b.text.contains(text):
			out.append(b)
	return out

func click_at(pos: Vector2) -> void:
	var motion := InputEventMouseMotion.new()
	motion.position = pos
	root.push_input(motion, true)
	await process_frame
	var press := InputEventMouseButton.new()
	press.button_index = MOUSE_BUTTON_LEFT
	press.pressed = true
	press.position = pos
	root.push_input(press, true)
	await process_frame
	var release := InputEventMouseButton.new()
	release.button_index = MOUSE_BUTTON_LEFT
	release.pressed = false
	release.position = pos
	root.push_input(release, true)
	await process_frame

func click_in(viewport: Viewport, pos: Vector2) -> void:
	var motion := InputEventMouseMotion.new()
	motion.position = pos
	viewport.push_input(motion, true)
	await process_frame
	var press := InputEventMouseButton.new()
	press.button_index = MOUSE_BUTTON_LEFT
	press.pressed = true
	press.position = pos
	viewport.push_input(press, true)
	await process_frame
	var release := InputEventMouseButton.new()
	release.button_index = MOUSE_BUTTON_LEFT
	release.pressed = false
	release.position = pos
	viewport.push_input(release, true)
	await process_frame

func drag_at(from: Vector2, to: Vector2, viewport: Viewport = null) -> void:
	var vp: Viewport = viewport if viewport != null else root
	var motion := InputEventMouseMotion.new()
	motion.position = from
	vp.push_input(motion, true)
	await process_frame
	var press := InputEventMouseButton.new()
	press.button_index = MOUSE_BUTTON_LEFT
	press.pressed = true
	press.position = from
	vp.push_input(press, true)
	await process_frame
	var steps := 12
	for i in range(1, steps + 1):
		var p := from.lerp(to, float(i) / steps)
		var move := InputEventMouseMotion.new()
		move.position = p
		vp.push_input(move, true)
		await process_frame
	var release := InputEventMouseButton.new()
	release.button_index = MOUSE_BUTTON_LEFT
	release.pressed = false
	release.position = to
	vp.push_input(release, true)
	await process_frame

func scroll_control_into_view(ctrl: Control, margin: int = 10) -> bool:
	var sc := main.scroll as ScrollContainer
	if sc == null:
		return true
	for i in range(12):
		var view: Rect2 = sc.get_global_rect()
		var r: Rect2 = ctrl.get_global_rect()
		var top: float = view.position.y + margin
		var bottom: float = view.end.y - margin
		if r.position.y < top:
			sc.scroll_vertical -= int(top - r.position.y) + 24
		elif r.end.y > bottom:
			sc.scroll_vertical += int(r.end.y - bottom) + 24
		else:
			return view.intersects(r)
		await process_frame
		await process_frame
	return sc.get_global_rect().intersects(ctrl.get_global_rect())

func click_control(ctrl: Control, margin: int = 10) -> void:
	if ctrl == null:
		return
	await scroll_control_into_view(ctrl, margin)
	await process_frame
	var vp: Viewport = ctrl.get_viewport()
	var r: Rect2 = ctrl.get_global_rect()
	await click_in(vp, r.position + r.size * 0.5)

func click_text(text: String, exact: bool = false) -> bool:
	var b := find_button(text, exact)
	if b == null:
		fail("button not found: " + text)
		return false
	log("click button '%s' enabled=%s" % [b.text.replace("\n", " "), str(not b.disabled)])
	await click_control(b)
	await create_timer(0.25).timeout
	return true

func state_line() -> String:
	var p: Dictionary = game.player
	return "flow=%s events=%d memories=%d cap=%d ink=%d erosion=%d status=%s" % [
		main.flow, p.completed_events.size(), p.memories.size(), int(p.capacity),
		int(p.ink_marks), int(p.erosion), main.status.text]

func _run() -> void:
	for a in OS.get_cmdline_user_args():
		if a.begins_with("--shots="):
			shots = a.trim_prefix("--shots=")
	DirAccess.make_dir_recursive_absolute(shots)
	ProjectSettings.set_setting("yanxia/server_url", "http://127.0.0.1:8097")
	main = load("res://scenes/main.tscn").instantiate()
	root.add_child(main)
	await create_timer(0.35).timeout
	await shot("splash")
	var deadline := Time.get_ticks_msec() + 25000
	while (main.busy or main.flow != "map") and Time.get_ticks_msec() < deadline:
		await process_frame
	if main.flow != "map":
		fail("never reached the map: " + main.status.text)
		quit(1)
		return
	game = root.get_node("GameState")
	log("reached map: " + state_line())
	await shot("map")
	await nav_pass()
	await settings_pass()
	for i in range(EVENTS.size()):
		await play_event(EVENTS[i][0], EVENTS[i][1], EVENTS[i][2], i + 1)
	await closing_pass()
	log("FINAL " + state_line())
	log("FAILURES=%d" % fails.size())
	for f in fails:
		log("  - " + f)
	quit(0)

func nav_pass() -> void:
	var pages := [
		["心舍 · 墨灵", "nav-memories"],
		["记忆账册", "nav-ledger"],
		["设置", "nav-settings"],
		["剧情 · 任务", "nav-journal"],
		["古建地图", "nav-map"],
	]
	for item in pages:
		await click_text(item[0], true)
		await create_timer(0.35).timeout
		await shot(item[1])
		log("nav '%s' -> %s" % [item[0], state_line()])

func settings_pass() -> void:
	await click_text("设置", true)
	await create_timer(0.3).timeout
	var slider := find_button("静音")
	if slider != null:
		await click_control(slider)
		await create_timer(0.2).timeout
		await shot("settings-muted")
	log("settings mute toggled")
	await click_text("保存设置", true)
	await create_timer(0.2).timeout
	await shot("settings-saved")

func play_event(chapter: String, event_id: String, title: String, index: int) -> void:
	log("=== EVENT %d %s/%s (%s)" % [index, chapter, event_id, title])
	if main.flow != "map":
		await click_text("古建地图", true)
		await create_timer(0.3).timeout
	var opened := await click_text("前往任务", true)
	if not opened:
		opened = await click_text(title, true)
	await create_timer(0.6).timeout
	if main.flow != "dialogue":
		fail("%s did not open the dialogue page (flow=%s, status=%s)" % [title, main.flow, main.status.text])
		return
	var tag := "%02d-%s" % [index, event_id]
	await shot(tag + "-dialogue-1")
	var lines: int = main.dialogue_lines.size()
	# next / previous
	await click_text("下一句", true)
	await shot(tag + "-dialogue-2")
	await click_text("上一句", true)
	if main.dialogue_index != 0:
		fail("%s: 上一句 did not step back (index=%d)" % [title, main.dialogue_index])
	if index == 1:
		# exercise the back button once, mid-dialogue
		await click_text("返回", true)
		await create_timer(0.3).timeout
		if main.flow != "map":
			fail("dialogue 返回 did not return to the map (flow=%s)" % main.flow)
		await shot(tag + "-dialogue-back")
		await click_text(title, true)
		await create_timer(0.5).timeout
		if main.flow != "dialogue":
			fail("%s: reopening the dialogue failed" % title)
			return
		if main.dialogue_index != 0:
			fail("%s: dialogue cursor was not restored" % title)
	for i in range(lines + 2):
		var next := find_button("下一句", true)
		if next == null:
			break
		if next.text != "下一句":
			break
		await click_control(next)
		await create_timer(0.05).timeout
	if main.flow == "dialogue":
		await shot(tag + "-dialogue-last")
		await click_text("对话结束 · 继续", true)
		await create_timer(0.6).timeout
	else:
		log("%s: dialogue left flow=%s" % [title, main.flow])
	if main.flow != "intro":
		fail("%s: dialogue did not hand over to the investigation scene (flow=%s)" % [title, main.flow])
		return
	await shot(tag + "-investigation-0")
	await investigate(index, title, tag)
	if main.flow != "intro":
		return
	await click_text("三处调查完成 · 开始修复", true)
	await create_timer(0.6).timeout
	await solve_loop(index, title, tag)

func investigate(index: int, title: String, tag: String) -> void:
	var scene: Control = main.scene_view
	var total: int = scene.investigations.size()
	for i in range(total):
		var raw: Array = scene.investigations[i].position
		var local: Vector2 = scene.size * Vector2(float(raw[0]), float(raw[1]))
		var global: Vector2 = scene.get_global_transform() * local
		await click_at(global)
		var deadline := Time.get_ticks_msec() + 4000
		while scene.discovered.size() <= i and Time.get_ticks_msec() < deadline:
			await process_frame
		await create_timer(0.25).timeout
		log("%s investigation %d '%s' discovered=%d/%d" % [title, i + 1, scene.investigations[i].label, scene.discovered.size(), total])
		if scene.discovered.size() <= i:
			fail("%s: investigation point '%s' was not discovered by clicking it" % [title, scene.investigations[i].label])
		if i == 0:
			await shot(tag + "-investigation-1")
	await shot(tag + "-investigation-3")

func solve_loop(index: int, title: String, tag: String) -> void:
	for round in range(14):
		if main.flow == "puzzle":
			await solve_step(index, title, tag)
		elif main.flow == "choice":
			await do_choice(index, title, tag)
		elif main.flow == "battle":
			await do_battle(index, title, tag)
		elif main.flow == "settlement":
			await settlement_pass(index, title, tag)
			return
		elif main.flow == "failed":
			await failed_pass(index, title, tag)
			return
		else:
			fail("%s: unexpected flow '%s' (%s)" % [title, main.flow, main.status.text])
			return

func current_step() -> Dictionary:
	var steps: Array = main.current_event.puzzle.steps
	var idx: int = int(game.session.accepted_steps.size())
	if idx >= steps.size():
		return {}
	return steps[idx]

func solve_step(index: int, title: String, tag: String) -> void:
	var step := current_step()
	if step.is_empty():
		fail("%s: no puzzle step but flow=puzzle" % title)
		return
	log("%s step '%s' kind=%s" % [title, step.id, step.kind])
	if step.kind == "trace":
		await solve_trace(index, title, tag, step)
	elif step.kind == "join":
		await click_control(main.join_canvas)
		var canvas: Control = main.join_canvas
		var answer: String = JOIN_ANSWERS.get(step.id, "")
		var slot: int = step.options.find(answer)
		if slot < 0:
			fail("%s: no known answer for join step %s" % [title, step.id])
			return
		var from: Vector2 = canvas.get_global_transform() * canvas.piece
		var to_local := Vector2(canvas.size.x * (slot + 0.5) / step.options.size(), 65)
		var to: Vector2 = canvas.get_global_transform() * to_local
		await drag_at(from, to)
		await create_timer(0.6).timeout
		log("%s join %s -> %s snapped=%s" % [title, step.id, answer, str(canvas.snapped)])
		if not canvas.snapped:
			fail("%s: join step %s did not accept the drag" % [title, step.id])
	elif step.kind == "skill":
		var skill: String = SKILL_STEPS.get(step.id, "")
		await click_text("使用「%s」" % skill, true)
		await create_timer(0.9).timeout
	elif step.kind == "choice":
		var answer2: String = CHOICE_ANSWERS.get(step.id, "")
		await click_text(answer2, true)
		await create_timer(0.6).timeout
	elif step.kind == "narrative":
		await shot(tag + "-narrative")
		await click_text(str(step.options[0]), true)
		await create_timer(0.6).timeout
	else:
		fail("%s: unknown step kind %s" % [title, step.kind])

func solve_trace(index: int, title: String, tag: String, step: Dictionary) -> void:
	var canvas: Control = main.trace_canvas
	await scroll_control_into_view(canvas)
	await shot(tag + "-trace-empty")
	var strokes: Array = step.trace.strokes
	var skip_last: bool = index == 1
	var last: int = strokes.size() - 1 if skip_last else strokes.size()
	for i in range(last):
		canvas.select_stroke(i)
		await process_frame
		await draw_stroke(canvas, strokes[i])
	if skip_last:
		log("%s: submitting with stroke %d missing on purpose" % [title, strokes.size()])
		await scroll_control_into_view(find_button("核对拓印", true))
		await shot(tag + "-trace-missing-stroke")
	else:
		await shot(tag + "-trace-drawn")
	var check := find_button("核对拓印", true)
	if check == null:
		fail("%s: 核对拓印 button missing" % title)
		return
	await click_control(check)
	await create_timer(1.0).timeout
	if skip_last:
		await shot(tag + "-trace-rejected")
		if main.flow != "puzzle":
			fail("%s: rejected trace left flow=%s" % [title, main.flow])
		else:
			var failed: Array = main.trace_canvas.failed
			log("%s: rejected trace marked strokes %s, status=%s" % [title, str(failed), main.status.text])
			if not failed.has(strokes.size() - 1):
				fail("%s: missing stroke was not marked as failed" % title)
			if main.trace_canvas.strokes.size() != strokes.size():
				fail("%s: rejected trace lost the drawing" % title)
			var redraw := find_button("重描本笔", true)
			if redraw != null:
				await click_control(redraw)
				log("%s: 重描本笔 cleared stroke %d" % [title, canvas.active])
			canvas.select_stroke(strokes.size() - 1)
			await process_frame
			await draw_stroke(canvas, strokes[strokes.size() - 1])
			await shot(tag + "-trace-repaired")
			await scroll_control_into_view(find_button("核对拓印", true))
			var check2 := find_button("核对拓印", true)
			await click_control(check2)
			await create_timer(1.2).timeout
	if main.flow == "puzzle" and not skip_last:
		fail("%s: trace step was not accepted (%s)" % [title, main.status.text])
	await create_timer(0.3).timeout

func draw_stroke(canvas: Control, stroke: Array) -> void:
	var pts: Array = []
	var offset := Vector2(0, canvas.canvas_rect.size.y * OFF_HAND)
	for point in stroke:
		var local: Vector2 = canvas.canvas_rect.position + Vector2((float(point[0]) - canvas.view_x) * canvas.characters, float(point[1])) * canvas.canvas_rect.size + offset
		pts.append(canvas.get_global_transform() * local)
	if pts.is_empty():
		return
	var vp: Viewport = canvas.get_viewport()
	var first := InputEventMouseButton.new()
	first.button_index = MOUSE_BUTTON_LEFT
	first.pressed = true
	first.position = pts[0]
	vp.push_input(first, true)
	await process_frame
	for i in range(1, pts.size()):
		var move := InputEventMouseMotion.new()
		move.position = pts[i]
		vp.push_input(move, true)
		await process_frame
	var release := InputEventMouseButton.new()
	release.button_index = MOUSE_BUTTON_LEFT
	release.pressed = false
	release.position = pts[pts.size() - 1]
	vp.push_input(release, true)
	await process_frame

func do_choice(index: int, title: String, tag: String) -> void:
	await shot(tag + "-choice")
	if not compared:
		compared = true
		var cmp := find_button("并排对比", false)
		if cmp != null:
			await click_control(cmp)
			await create_timer(0.4).timeout
			await shot(tag + "-compare")
			var back := find_button("返回抉择", true)
			if back == null:
				fail("compare page has no 返回抉择 button")
			else:
				await click_control(back)
				await create_timer(0.4).timeout
				if main.flow != "choice":
					fail("compare page did not return to the choice page (flow=%s)" % main.flow)
	var keep := find_button("拓印这道墨灵", true)
	if keep != null and not keep.disabled:
		await click_control(keep)
		await create_timer(1.0).timeout
		log("%s chose keep" % title)
		return
	var forget_list := find_buttons_like("抹去「")
	if forget_list.is_empty():
		fail("%s: cannot keep (capacity full) and no forget button exists" % title)
		return
	await click_control(forget_list[0])
	await create_timer(0.5).timeout
	await shot(tag + "-forget-dialog")
	if not main.confirmation.visible:
		fail("%s: confirmation dialog did not open" % title)
	if not dialog_cancel_tested:
		dialog_cancel_tested = true
		var cancel := find_button("留下这段记忆", true)
		if cancel != null:
			await click_in(main.confirmation, cancel.get_global_rect().position + cancel.get_global_rect().size * 0.5)
			await create_timer(0.4).timeout
			log("confirmation cancel tested, dialog visible=%s" % str(main.confirmation.visible))
			await click_control(forget_list[0])
			await create_timer(0.5).timeout
	var ok := find_button("亲手抹去", true)
	if ok == null:
		fail("%s: confirmation dialog has no 亲手抹去 button" % title)
		return
	await click_in(main.confirmation, ok.get_global_rect().position + ok.get_global_rect().size * 0.5)
	await create_timer(1.2).timeout
	log("%s chose forget: %s" % [title, state_line()])

func do_battle(index: int, title: String, tag: String) -> void:
	await shot(tag + "-battle-ready")
	var start := find_button("开始守护", false)
	if start == null:
		fail("%s: battle start button missing" % title)
		return
	await click_control(start)
	Engine.time_scale = 4.0
	await create_timer(0.4).timeout
	var required: Array = main.current_event.battle.required_skills
	var used := {}
	var guard := 0
	while not main.battle_finished and guard < 3000:
		guard += 1
		var did := false
		for skill in required:
			if used.has(skill):
				continue
			var b := find_button(str(skill), false)
			if b != null and not b.disabled:
				await click_control(b)
				used[skill] = true
				did = true
				break
		if not did:
			var attack := find_button("挥墨", false)
			if attack != null and not attack.disabled:
				if guard % 7 == 0:
					await shot(tag + "-battle-%d" % guard)
				await click_control(attack)
		await process_frame
	Engine.time_scale = 1.0
	await create_timer(0.4).timeout
	await shot(tag + "-battle-over")
	log("%s battle finished=%s waves=%d hits=%d status=%s" % [title, str(main.battle_finished), main.battle_wave, main.battle_hits, main.status.text])
	var settle := find_button("结算白蚀战斗", true)
	if settle == null:
		fail("%s: battle end has no 结算白蚀战斗 button (status=%s)" % [title, main.status.text])
		return
	await click_control(settle)
	await create_timer(1.2).timeout

func settlement_pass(index: int, title: String, tag: String) -> void:
	await shot(tag + "-settlement")
	log("%s settlement: %s" % [title, state_line()])
	var look := find_button("回看这道墨灵", true)
	if look == null:
		fail("%s: settlement has no 回看这道墨灵 button" % title)
	else:
		await click_control(look)
		await create_timer(0.5).timeout
		await shot(tag + "-memory-detail")
		var echo := find_button("聆听墨灵回声", false)
		if echo != null:
			await click_control(echo)
			await create_timer(1.0).timeout
			await shot(tag + "-echo-playing")
			var pause := find_button("暂停回声", false)
			if pause != null:
				await click_control(pause)
				await create_timer(0.5).timeout
				await shot(tag + "-echo-paused")
			else:
				log("%s: echo button showed '%s' after playing" % [title, find_button("回声", false).text if find_button("回声", false) != null else "none"])
		else:
			log("%s: memory detail has no echo button (may be a forgotten memory)" % title)
		await click_text("返回心舍", true)
		await create_timer(0.4).timeout
		await shot(tag + "-heart-room")
	await click_text("古建地图", true)
	await create_timer(0.4).timeout

func failed_pass(index: int, title: String, tag: String) -> void:
	await shot(tag + "-failed")
	log("%s FAILED: %s" % [title, state_line()])
	fail("%s: event failed during the review run" % title)
	await click_text("返回古建地图", true)
	await create_timer(0.4).timeout

func closing_pass() -> void:
	await click_text("记忆账册", true)
	await create_timer(0.4).timeout
	await shot("ledger-full")
	await click_text("剧情 · 任务", true)
	await create_timer(0.4).timeout
	await shot("journal-full")
	var replay := find_buttons_like(" / ")
	if not replay.is_empty():
		await click_control(replay[0])
		await create_timer(0.5).timeout
		await shot("journal-replay")
		log("journal replay flow=%s lines=%d" % [main.flow, main.dialogue_lines.size()])
		await click_text("跳过对话 · 继续", true)
		await create_timer(0.4).timeout
	await click_text("心舍 · 墨灵", true)
	await create_timer(0.4).timeout
	await shot("heart-room-full")
	var tiles := find_buttons_like("格")
	if not tiles.is_empty():
		await click_control(tiles[0])
		await create_timer(0.5).timeout
		await shot("memory-detail-from-heart")
		await click_text("返回心舍", true)
		await create_timer(0.3).timeout
	await click_text("古建地图", true)
	await create_timer(0.4).timeout
	await shot("map-final")
"}

