{"content": "extends SceneTree

# Second review harness: dialogue skip button, heart-room pause during a puzzle,
# wrong-answer failure page, rewind, and the settings slider.
# Runs against a throwaway copy of the client; nothing in the repository is touched.

const OFF_HAND := 0.03

var main: Node
var game: Node
var shots := ""
var shot_no := 0
var fails: Array[String] = []
var logfile: FileAccess

func _initialize() -> void:
	_run.call_deferred()

func note(msg: String) -> void:
	var line := "[REVIEW2 %7d] %s" % [Time.get_ticks_msec(), msg]
	print(line)
	if logfile == null and not shots.is_empty():
		logfile = FileAccess.open(shots.path_join("driver2.log"), FileAccess.WRITE)
	if logfile != null:
		logfile.store_line(line)
		logfile.flush()

func fail(msg: String) -> void:
	fails.append(msg)
	note("FAIL " + msg)

func shot(name: String) -> void:
	shot_no += 1
	await process_frame
	await process_frame
	RenderingServer.force_draw()
	root.get_texture().get_image().save_png(shots.path_join("P%03d-%s.png" % [shot_no, name]))
	note("shot P%03d-%s" % [shot_no, name])

func collect_buttons(node: Node, out: Array) -> void:
	for child in node.get_children():
		if child is Button:
			out.append(child)
		collect_buttons(child, out)

func find_button(text: String, exact: bool = false) -> Button:
	var list: Array = []
	collect_buttons(main, list)
	for b in list:
