{"content": "extends SceneTree

# Probe: finish the stuck archway choice (capacity is full) and find out why the
# confirmation dialog's buttons could not be reached from the main scene tree.

var main: Node
var game: Node
var shots := ""
var logfile: FileAccess

func _initialize() -> void:
	_run.call_deferred()

func note(msg: String) -> void:
	print("[REVIEW3] " + msg)
	if logfile == null and not shots.is_empty():
		logfile = FileAccess.open(shots.path_join("driver3.log"), FileAccess.WRITE)
	if logfile != null:
		logfile.store_line(msg)
		logfile.flush()

func collect_buttons(node: Node, out: Array) -> void:
	for child in node.get_children():
		if child is Button:
			out.append(child)
		collect_buttons(child, out)

func find_button(text: String) -> Button:
	var list: Array = []
	collect_buttons(main, list)
	for b in list:
		if b.text.contains(text):
			return b
	return null

func click_in(viewport: Viewport, pos: Vector2) -> void:
	viewport.push_input(_motion(pos), true)
	await process_frame
	var press := InputEventMouseButton.new()
	press.button_index = MOUSE_BUTTON_LEFT
	press.pressed = true
	press.position = pos
	viewport.push_input(press, true)
	await process_frame
	var release := InputEventMouseButton.new()
	release.button_index = MOUSE_BUTTON_LEFT
	release.pressed = false
	release.position = pos
	viewport.push_input(release, true)
	await process_frame

func _motion(p: Vector2) -> InputEventMouseMotion:
	var m := InputEventMouseMotion.new()
	m.position = p
	return m

func click_control(ctrl: Control) -> void:
	var sc := main.scroll as ScrollContainer
	if sc != null:
		for i in range(10):
			var view: Rect2 = sc.get_global_rect()
			var r0: Rect2 = ctrl.get_global_rect()
			if r0.position.y < view.position.y + 10:
				sc.scroll_vertical -= int(view.position.y + 10 - r0.position.y) + 24
			elif r0.end.y > view.end.y - 10:
				sc.scroll_vertical += int(r0.end.y - (view.end.y - 10)) + 24
			else:
				break
			await process_frame
			await process_frame
	var r: Rect2 = ctrl.get_global_rect()
	await click_in(ctrl.get_viewport(), r.position + r.size * 0.5)

func shot(name: String) -> void:
	await process_frame
	await process_frame
	RenderingServer.force_draw()
	root.get_texture().get_image().save_png(shots.path_join(name + ".png"))
	note("shot " + name)

func _run() -> void:
	for a in OS.get_cmdline_user_args():
		if a.begins_with("--shots="):
			shots = a.trim_prefix("--shots=")
	DirAccess.make_dir_recursive_absolute(shots)
	ProjectSettings.set_setting("yanxia/server_url", "http://127.0.0.1:8097")
	main = load("res://scenes/main.tscn").instantiate()
	root.add_child(main)
	var deadline := Time.get_ticks_msec() + 25000
	while (main.busy or main.flow != "map") and Time.get_ticks_msec() < deadline:
		await process_frame
	game = root.get_node("GameState")
	note("map reached, flow=%s session=%s" % [main.flow, main.session_id])
	# resume whatever session is open
	var resume := find_button("继续当前修复")
	if resume != null:
		note("resuming open session")
		await click_control(resume)
		await create_timer(0.8).timeout
	note("after resume: flow=%s" % main.flow)
	await shot("A-after-resume")
	if main.flow == "choice":
		var forgets: Array = []
		collect_buttons(main, forgets)
		var target: Button = null
		for b in forgets:
			if b.text.contains("抹去「"):
				target = b
				break
		if target == null:
			note("no forget button on the choice page")
			quit(1)
			return
		note("clicking forget: " + target.text)
		await click_control(target)
		await create_timer(0.6).timeout
		note("dialog visible=%s" % str(main.confirmation.visible))
		await shot("B-dialog")
		# dump every button reachable from main, and every button in the dialog
		var pool: Array = []
		collect_buttons(main, pool)
		note("--- buttons from main (%d) ---" % pool.size())
		for b in pool:
			note("  '%s' visible=%s in_tree=%s vp_root=%s" % [b.text.replace("\n", "/"), str(b.visible), str(b.is_visible_in_tree()), str(b.get_viewport() == root)])
		var dlg: Array = []
		collect_buttons(main.confirmation, dlg)
		note("--- buttons inside the dialog node (%d) ---" % dlg.size())
		for b in dlg:
			note("  '%s' visible=%s in_tree=%s" % [b.text.replace("\n", "/"), str(b.visible), str(b.is_visible_in_tree())])
		var ok := main.confirmation.get_ok_button()
		var cancel := main.confirmation.get_cancel_button()
		note("get_ok_button='%s' get_cancel_button='%s'" % [ok.text, cancel.text])
		await click_control(ok)
		await create_timer(1.5).timeout
		note("after confirming: flow=%s status=%s ink=%d memories=%d" % [main.flow, main.status.text, int(game.player.ink_marks), game.player.memories.size()])
		await shot("C-after-confirm")
	quit(0)
", "file_path": "C:\Users\Admin\AppData\Local\Temp\dsh-3MreNI\yanxia-review\client\review_driver3.gd"}

