	while (main.busy or main.flow != "map") and Time.get_ticks_msec() < deadline:
		await process_frame
	var resume := find_button("继续当前修复")
	if resume != null:
		await click_control(resume)
		await create_timer(0.8).timeout
	if main.flow != "choice":
		# try the nav, then the resume button again
		var nav := find_button("古建地图")
		if nav != null:
			await click_control(nav)
			await create_timer(0.5).timeout
			var r2 := find_button("继续当前修复")
