		return
	var forget_list := find_buttons_like("\u62b9\u53bb\u300c")
	if forget_list.is_empty():
		fail("%s: cannot keep and no forget button exists" % title)
		return
	await click_control(forget_list[0])
	await create_timer(0.9).timeout
	await shot(tag + "-forget-dialog")
	if not main.confirmation.visible:
		fail("%s: confirmation dialog did not open" % title)
		return
	if not dialog_cancel_tested:
		dialog_cancel_tested = true
		var cancel: Button = main.confirmation.get_cancel_button()
		await click_dialog_button(cancel)
		await create_timer(0.7).timeout
		note("cancel tested: dialog=%s flow=%s" % [str(main.confirmation.visible), main.flow])
		if main.flow != "choice":
			fail("%s: the cancel button did not leave the choice page intact (flow=%s)" % [title, main.flow])
			return
		await click_control(forget_list[0])
		await create_timer(0.9).timeout
	var ok: Button = main.confirmation.get_ok_button()
	await click_dialog_button(ok)
	await create_timer(1.6).timeout
	note("%s chose forget: %s" % [title, state_line()])

func click_dialog_button(b: Button) -> void:
	if b == null:
		fail("confirmation dialog button is missing")
		return
	await create_timer(0.4).timeout
	var r: Rect2 = b.get_global_rect()
	var dpos: Vector2 = main.confirmation.position
	note("dialog button '%s' local=%s dialog_origin=%s" % [b.text, str(r), str(dpos)])
	await click_at(dpos + r.position + r.size * 0.5)

