{"command": "$t = 'C:\Users\Admin\AppData\Local\Temp\dsh-3MreNI\yanxia-review'
$code = @'
extends SceneTree
# Probe: what happens at erosion 100 - can the player recover through rewind?

var main: Node
var shots := ""
var logfile: FileAccess

func _initialize() -> void:
	_run.call_deferred()

func note(msg: String) -> void:
	print("[PROBE6] " + msg)
	if logfile == null and not shots.is_empty():
		logfile = FileAccess.open(shots.path_join("probe6.log"), FileAccess.WRITE)
	if logfile != null:
		logfile.store_line(msg)
		logfile.flush()

func collect_buttons(node: Node, out: Array) -> void:
	for child in node.get_children():
		if child is Button:
			out.append(child)
		collect_buttons(child, out)

func button_pool() -> Array:
	var list: Array = []
	collect_buttons(main, list)
	if main.confirmation != null:
		collect_buttons(main.confirmation, list)
	return list

func find_button(text: String) -> Button:
	for b in button_pool():
		if not b.visible:
			continue
		if b.get_viewport() == root and not b.is_visible_in_tree():
			continue
		if b.text.contains(text):
			return b
	return null

func click_root(pos: Vector2) -> void:
	var m := InputEventMouseMotion.new()
	m.position = pos
	root.push_input(m, true)
	await process_frame
	var p := InputEventMouseButton.new()
	p.button_index = MOUSE_BUTTON_LEFT
	p.pressed = true
	p.position = pos
	root.push_input(p, true)
	await process_frame
	var r := InputEventMouseButton.new()
	r.button_index = MOUSE_BUTTON_LEFT
	r.pressed = false
	r.position = pos
	root.push_input(r, true)
	await process_frame

func click_control(ctrl: Control) -> void:
	var sc := main.scroll as ScrollContainer
	if sc != null:
		for i in range(12):
			var view: Rect2 = sc.get_global_rect()
			var r0: Rect2 = ctrl.get_global_rect()
			if r0.position.y < view.position.y + 10:
				sc.scroll_vertical -= int(view.position.y + 10 - r0.position.y) + 24
			elif r0.end.y > view.end.y - 10:
				sc.scroll_vertical += int(r0.end.y - (view.end.y - 10)) + 24
			else:
				break
			await process_frame
			await process_frame
	var r: Rect2 = ctrl.get_global_rect()
	await click_root(r.position + r.size * 0.5)

func shot(name: String) -> void:
	await process_frame
	await process_frame
	RenderingServer.force_draw()
	root.get_texture().get_image().save_png(shots.path_join(name + ".png"))

func p() -> Dictionary:
	return root.get_node("/root/GameState").player

func _run() -> void:
	for a in OS.get_cmdline_user_args():
		if a.begins_with("--shots="):
			shots = a.trim_prefix("--shots=")
	DirAccess.make_dir_recursive_absolute(shots)
	ProjectSettings.set_setting("yanxia/server_url", "http://127.0.0.1:8097")
	main = load("res://scenes/main.tscn").instantiate()
	root.add_child(main)
	var deadline := Time.get_ticks_msec() + 25000
	while (main.busy or main.flow != "map") and Time.get_ticks_msec() < deadline:
		await process_frame
	note("map: erosion=%d ink=%d session=%s" % [int(p().erosion), int(p().ink_marks), main.session_id])
	await shot("J1-map-at-100-erosion")
	var resume := find_button("\u7ee7\u7eed\u5f53\u524d\u4fee\u590d")
	if resume != null:
		note("button: " + resume.text)
		await click_control(resume)
		await create_timer(1.0).timeout
	note("flow=%s status=%s" % [main.flow, main.status.text])
	await shot("J2-failure-page")
	var rw := find_button("\u56de\u6eaf")
	if rw == null:
		note("no rewind button on the failure page")
		quit(1)
		return
	note("rewind button text: '%s' disabled=%s" % [rw.text, str(rw.disabled)])
	var before_erosion := int(p().erosion)
	var before_ink := int(p().ink_marks)
	await click_control(rw)
	await create_timer(1.6).timeout
	note("after rewind: flow=%s erosion=%d (was %d) ink=%d (was %d)" % [main.flow, int(p().erosion), before_erosion, int(p().ink_marks), before_ink])
	note("status=" + main.status.text)
	await shot("J3-after-rewind")
	note("canvas/stage: puzzle steps accepted=%d" % (main.game_state_check() if false else 0))
	quit(0)
'@
$path = Join-Path $t 'client\review_driver6.gd'
[System.IO.File]::WriteAllText($path, $code, (New-Object System.Text.UTF8Encoding($false)))
$env:APPDATA = Join-Path $t 'appdata-client'
& "$t\Godot_v4.5.2-stable_win64_console.exe" --headless --path "$t\client" --check-only --script res://review_driver6.gd
"parse exit=$LASTEXITCODE"", "description": "Write and parse-check the rewind probe"}

